import {mountScenePreview} from './studio-preview.mjs';
const $=id=>document.getElementById(id);let draft=null,moduleCatalog={},expandedSections=new Set(['Game project','Locations','Characters','Scripted scenes']);
const node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
async function api(path,body){const r=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const v=await r.json();if(!r.ok)throw Error(v.error||'Request failed');return v;}
function message(s){$('studio-status').textContent=s;}
function fail(e){message(e.message);}
function option(select,value,label){const o=node('option',label);o.value=value;select.append(o);}
async function refresh(){const [d,b]=await Promise.all([api('/api/studio/list'),api('/api/bootstrap')]);moduleCatalog=b.modules||{};$('draft-list').replaceChildren();option($('draft-list'),'','Open a draft…');for(const x of d.drafts)option($('draft-list'),x.id,x.title+' · '+new Date(x.updated).toLocaleDateString());$('clone').replaceChildren();option($('clone'),'','Copy a game project…');for(const p of b.packs)option($('clone'),p.id,p.title);}
function field(parent,obj,key,label,kind='text',choices){const wrap=node('label');wrap.className='studio-field';wrap.append(node('span',label));let input;if(choices){input=node('select');for(const [v,l] of choices)option(input,v,l);}else input=node(kind==='long'?'textarea':'input');if(kind==='number')input.type='number';input.value=obj[key]??'';input.oninput=()=>{obj[key]=kind==='number'?Number(input.value):input.value;message('Unsaved changes');};wrap.append(input);parent.append(wrap);return input;}
async function preparedImage(file,kind){if(file.size>20000000)throw Error('Choose an image file smaller than 20 MB.');const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});try{if(bitmap.width>8192||bitmap.height>8192||bitmap.width*bitmap.height>40000000)throw Error('This image is too large to process safely. Resize it below 40 megapixels first.');const canvas=document.createElement('canvas');if(kind==='background'){canvas.width=1920;canvas.height=1080;const sourceRatio=bitmap.width/bitmap.height,targetRatio=16/9;let sx=0,sy=0,sw=bitmap.width,sh=bitmap.height;if(sourceRatio>targetRatio){sw=bitmap.height*targetRatio;sx=(bitmap.width-sw)/2;}else{sh=bitmap.width/targetRatio;sy=(bitmap.height-sh)/2;}canvas.getContext('2d',{alpha:false}).drawImage(bitmap,sx,sy,sw,sh,0,0,1920,1080);for(const quality of [.9,.84,.78,.72,.66]){const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(blob&&blob.size<=3500000)return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not prepare image.'));reader.readAsDataURL(blob);});}throw Error('This background is still too large after resizing. Try a simpler or lower-detail image.');}
if(kind==='character'){if(file.type!=='image/png')throw Error('Character art must be a PNG with transparency.');const check=document.createElement('canvas');check.width=512;check.height=512;const checkCtx=check.getContext('2d',{willReadFrequently:true});checkCtx.clearRect(0,0,512,512);checkCtx.drawImage(bitmap,0,0,512,512);const pixels=checkCtx.getImageData(0,0,512,512).data;let transparent=false;for(let i=3;i<pixels.length;i+=4)if(pixels[i]<250){transparent=true;break;}if(!transparent)throw Error('This PNG has no transparent pixels. Remove its background, then upload it again.');canvas.width=1024;canvas.height=1536;const scale=Math.min(1024/bitmap.width,1536/bitmap.height),w=Math.round(bitmap.width*scale),h=Math.round(bitmap.height*scale);canvas.getContext('2d').clearRect(0,0,1024,1536);canvas.getContext('2d').drawImage(bitmap,(1024-w)/2,(1536-h)/2,w,h);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob||blob.size>3500000)throw Error('The prepared character PNG exceeds 3.5 MB. Reduce its detail or resize the source image.');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not prepare image.'));reader.readAsDataURL(blob);});}throw Error('Unknown image type.');}finally{bitmap.close();}}
function imageUpload(parent,obj,key,label,kind){const wrap=node('div');wrap.className='studio-field';wrap.append(node('span',label));const help=kind==='background'?'Recommended: 16:9 landscape. The builder center-crops and resizes to 1920 × 1080 JPEG.':'Transparent PNG only. The builder fits the character onto a 1024 × 1536 transparent canvas.';const hint=node('small',help);hint.className='asset-hint';wrap.append(hint);const row=node('div');row.className='studio-image '+kind;if(obj[key]){const preview=node('img');preview.src=obj[key];preview.alt='';row.append(preview);}const input=node('input');input.type='file';input.accept=kind==='character'?'image/png': 'image/png,image/jpeg,image/webp';input.onchange=async()=>{try{const file=input.files?.[0];if(!file)return;message('Preparing image…');const data=await preparedImage(file,kind);const result=await api('/api/studio/asset',{data,kind});obj[key]=result.path;render();message(kind==='background'?'Background cropped to 16:9 and optimized.':'Character art prepared as a transparent PNG.');}catch(e){fail(e);}finally{input.value='';}};row.append(input);if(obj[key]){const clear=node('button','Remove');clear.onclick=()=>{delete obj[key];render();message('Unsaved changes');};row.append(clear);}wrap.append(row);parent.append(wrap);}
const list=s=>s.split(',').map(x=>x.trim()).filter(Boolean);
function csv(parent,obj,key,label){const temp={value:(obj[key]||[]).join(', ')};const input=field(parent,temp,'value',label);input.oninput=()=>{obj[key]=list(input.value);message('Unsaved changes');};}
function section(title,help){const s=node('details');s.className='studio-section';s.dataset.title=title;s.open=expandedSections.has(title);s.ontoggle=()=>{if(s.open)expandedSections.add(title);else expandedSections.delete(title);};const summary=node('summary');summary.append(node('span',title));s.append(summary,node('p',help));$('fields').append(s);return s;}
function updateNavigation(){const nav=$('studio-nav');nav.replaceChildren(node('strong','Project sections'));for(const section of $('fields').children){const button=node('button',section.dataset.title);button.type='button';button.className='studio-nav-link';button.onclick=()=>{section.open=true;expandedSections.add(section.dataset.title);section.scrollIntoView({behavior:'smooth',block:'start'});};nav.append(button);}}
function setModule(id,enabled){const enable=(key,seen=new Set())=>{if(seen.has(key))return;seen.add(key);const meta=moduleCatalog[key];if(!meta)return;for(const dep of meta.requires||[])enable(dep,seen);draft.pack.modules[key]=meta.version;if(key==='world.daypart'&&!draft.pack.daypart)draft.pack.daypart={interval:4,labels:['Morning','Afternoon','Evening'],introLocation:draft.pack.locations[0]?.id||'start',event:'',hangouts:[],backgroundOnly:[]};if(key==='social.npc')draft.pack.initialNpcRelationships||=[];if(key==='world.economy')draft.pack.initialMoney??=100;if(key==='world.events')draft.pack.worldEvents||=[];if(key==='story.scenes')draft.pack.scriptedScenes||=[];if(key==='items.inventory')draft.pack.items||=[];if(key==='items.equipment'&&!draft.pack.equipmentSlots?.length)draft.pack.equipmentSlots=['outfit','accessory','tool'];if(key==='social.bonds'){if(!draft.pack.relationshipDimensions?.length)draft.pack.relationshipDimensions=[{id:'affection',name:'Affection'},{id:'rivalry',name:'Rivalry'},{id:'familiarity',name:'Familiarity'}];draft.pack.initialBonds||=[];}if(key==='world.objects')draft.pack.objects||=[];if(key==='story.quests')draft.pack.quests||=[];if(key==='powers.abilities'){draft.pack.abilities||=[];draft.pack.resource||={name:'Energy',max:5,restAt:draft.pack.locations[0]?.id||'start'};}};const disable=(key,seen=new Set())=>{if(seen.has(key))return;seen.add(key);for(const [child,meta] of Object.entries(moduleCatalog))if(draft.pack.modules[child]&&(meta.requires||[]).includes(key))disable(child,seen);delete draft.pack.modules[key];};enabled?enable(id):disable(id);render();message('Module set changed. Existing project data is kept but inactive until its module is enabled.');}
function moduleEditor(){const s=section('Gameplay modules','Compose each game from small systems. Dependencies enable automatically; turning a system off also turns off its dependants. Data stays in the project when a system is disabled.');for(const meta of Object.values(moduleCatalog)){const row=node('div');row.className='module-row';const check=node('input');check.type='checkbox';check.checked=!!draft.pack.modules[meta.id];check.onchange=()=>setModule(meta.id,check.checked);const text=node('div');text.append(node('strong',meta.title),node('p',meta.description));if(meta.requires?.length)text.append(node('small','Needs: '+meta.requires.map(id=>moduleCatalog[id]?.title||id).join(', ')));row.append(check,text);s.append(row);}}
function rows(title,help,key,defaults,fields){const s=section(title,help);for(const [i,row] of draft.pack[key].entries()){const c=node('article');c.className='studio-card';c.append(node('h3',`${title.slice(0,-1)} ${i+1}`));const grid=node('div');grid.className='studio-grid';fields(grid,row);c.append(grid);const remove=node('button','Remove');remove.onclick=()=>{draft.pack[key].splice(i,1);render();message('Unsaved changes');};c.append(remove);s.append(c);}const add=node('button','+ Add '+title.slice(0,-1).toLowerCase());add.onclick=()=>{draft.pack[key].push(structuredClone(defaults));render();message('Unsaved changes');};s.append(add);}
const locs=()=>draft.pack.locations.map(l=>[l.id,l.name+' ('+l.id+')']);
const actors=()=>draft.pack.actors.map(a=>[a.id,a.name+' ('+a.id+')']);
function locationField(g,o,key,label){field(g,o,key,label,'text',locs());}
function poseEditor(parent,actor){
 actor.poses||=[];
 const section=node('div');section.className='studio-card';section.append(node('strong','Pose variants (transparent PNG)'));
 for(const [i,pose] of actor.poses.entries()){
  const row=node('div');row.className='studio-grid';field(row,pose,'id','Pose ID');imageUpload(row,pose,'image','Pose image','character');
  const remove=node('button','Remove pose');remove.onclick=()=>{actor.poses.splice(i,1);render();};row.append(remove);section.append(row);
 }
 const add=node('button','+ Add pose');add.onclick=()=>{actor.poses.push({id:'pose-'+(actor.poses.length+1)});render();};section.append(add);parent.append(section);
}
function extraConditionFields(parent,when,p){
 if(p.modules['items.equipment']){const input=field(parent,{value:(when.equipped||[]).join(', ')},'value','Required equipped item IDs');input.oninput=()=>{if(input.value.trim())when.equipped=list(input.value);else delete when.equipped;message('Unsaved changes');};}
 if(p.modules['social.bonds']){
  for(const [index,rule] of (when.bonds||[]).entries()){const row=node('div');row.className='studio-grid';field(row,rule,'character','Character','text',actors().filter(([id])=>id!==p.playerId));field(row,rule,'dimension','Dimension','text',p.relationshipDimensions.map(d=>[d.id,d.name]));field(row,rule,'min','Minimum value','number');const remove=node('button','Remove dimension requirement');remove.onclick=()=>{when.bonds.splice(index,1);if(!when.bonds.length)delete when.bonds;render();};row.append(remove);parent.append(row);}
  const add=node('button','+ Require relationship value');add.onclick=()=>{when.bonds||=[];when.bonds.push({character:p.actors.find(a=>a.id!==p.playerId)?.id||'',dimension:p.relationshipDimensions[0]?.id||'',min:1});render();};parent.append(add);
 }
}
