  field(grid,scene.when,'location','Required location','text',[['','Anywhere'],...locs()]);field(grid,scene.when,'minTick','Earliest tick','number');field(grid,scene.when,'maxTick','Latest tick (optional)','number');csv(grid,scene.when,'weekdays','Allowed weekdays (Monday, Friday, etc.)');csv(grid,scene.when,'dayparts','Allowed parts (Morning, Afternoon, Evening)');
