   if(e.type==='flag'){field(box,e,'id','Flag ID');const val=field(box,{value:e.value?'yes':'no'},'value','Flag value','text',[['yes','True'],['no','False']]);val.onchange=()=>{e.value=val.value==='yes';message('Unsaved changes');};}
